package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * INTEREST RUN
 * CHG 17.01.2001 - rounding added after complaint from branch 0042
 */
public class InterestCalculator {

    public BigDecimal monthlyInterest(BigDecimal balance, BigDecimal annualRatePercent) {
        // balance * annualRatePercent / 100 / 12
        // We divide by 1200 to combine the /100 and /12
        return balance.multiply(annualRatePercent)
                .divide(new BigDecimal("1200"), 2, RoundingMode.HALF_UP);
    }
}

