package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * SPLIT PAYMENTS (standing orders to several payees)
 */
public class PaymentSplitter {

    /** 
     * Returns an array of shares in cents for each payee.
     * The remainder cents are distributed one by one to the front of the list.
     */
    public long[] calculateShares(BigDecimal total, int payees) {
        long totalCents = total.movePointRight(2).setScale(0, RoundingMode.HALF_UP).longValue();
        long baseShareCents = totalCents / payees;
        long remainderCents = totalCents % payees;

        long[] shares = new long[payees];
        for (int i = 0; i < payees; i++) {
            shares[i] = baseShareCents + (i < remainderCents ? 1 : 0);
        }
        return shares;
    }
}

